use ingetrazo_core::sheet_shape::ShapePath;use glam::DVec2;use ingetrazo_render::qt_gray::Segment;
fn main(){let args=std::env::args().collect::<Vec<_>>();let v:serde_json::Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let size=DVec2::new(v["size"][0].as_f64().unwrap(),v["size"][1].as_f64().unwrap());let path=if v["kind"]=="ellipse"{ShapePath::Ellipse{size}}else{ShapePath::RoundedRect{size,radius:v["radius"].as_f64().unwrap()}};let path=ingetrazo_gui::composer_cad::source_closed_curve(&path).unwrap();let paths=ingetrazo_gui::composer_cad::source_curve_stroke(&path,v["width"].as_f64().unwrap()/2.).unwrap();let rows=paths.iter().map(|p|serde_json::json!({"start":p.start,"segments":p.segments.iter().map(|s|match s{Segment::Line(to)=>serde_json::json!({"line":to}),Segment::Cubic{control1,control2,to}=>serde_json::json!({"cubic":[control1,control2,to]})}).collect::<Vec<_>>()})).collect::<Vec<_>>();std::fs::write(&args[2],serde_json::to_vec(&rows).unwrap()).unwrap();}
